import{_ as o,c as a,o as t,a3 as r}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Sales","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/sales/index.md","filePath":"master/sales/sales/index.md","lastUpdated":1792041590000}'),i={name:"master/sales/sales/index.md"};function s(n,e,l,u,d,c){return t(),a("div",null,e[0]||(e[0]=[r('<h1 id="sales" tabindex="-1">Sales <a class="header-anchor" href="#sales" aria-label="Permalink to &quot;Sales&quot;">​</a></h1><p>The <strong>Sales</strong> module takes a customer from first quote to final invoice. Use it to prepare quotations, confirm them as sales orders, manage your products and prices, and invoice what you sold.</p><p>Everything follows one flow: a <strong>customer</strong> receives a <strong>quotation</strong>, the quotation is <strong>confirmed</strong> as a sales order, and the order is <strong>invoiced</strong>.</p><blockquote><p><strong>In simple words:</strong> Sales is where you quote, sell and invoice.</p></blockquote><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><p>Set up in this order: <a href="./configuration/">Configuration</a>, then <a href="./products-prices/">Products and prices</a>, then <a href="./quotations-orders/">Quotations and orders</a> (add the customer first), then <a href="./invoicing/">Invoicing</a>.</p><h2 id="how-the-module-is-organised" tabindex="-1">How the module is organised <a class="header-anchor" href="#how-the-module-is-organised" aria-label="Permalink to &quot;How the module is organised&quot;">​</a></h2><h3 id="quotations-and-orders" tabindex="-1">Quotations and orders <a class="header-anchor" href="#quotations-and-orders" aria-label="Permalink to &quot;Quotations and orders&quot;">​</a></h3><p>Create quotes, send them and turn them into orders.</p><ul><li><a href="./quotations-orders/">Quotations and orders</a>: overview of the group.</li><li><a href="./quotations-orders/create-quotation.html">Create a quotation</a>: build a quote with order lines.</li><li><a href="./quotations-orders/optional-products.html">Optional products</a>: suggest extra items on a quote.</li><li><a href="./quotations-orders/send-and-confirm-quotation.html">Send and confirm a quotation</a>: email the quote and confirm it.</li><li><a href="./quotations-orders/manage-orders.html">Manage orders</a>: follow confirmed orders.</li><li><a href="./quotations-orders/manage-customers.html">Manage customers</a>: keep the people you sell to.</li></ul><h3 id="invoicing" tabindex="-1">Invoicing <a class="header-anchor" href="#invoicing" aria-label="Permalink to &quot;Invoicing&quot;">​</a></h3><p>Invoice the customer for what you sold.</p><ul><li><a href="./invoicing/">Invoicing</a>: overview of the group.</li><li><a href="./invoicing/invoicing-policies.html">Invoicing policies</a>: invoice ordered or delivered quantities.</li><li><a href="./invoicing/order-to-invoice.html">Order to invoice</a>: orders that are ready to invoice.</li><li><a href="./invoicing/order-to-upsell.html">Order to upsell</a>: orders where you can sell more.</li></ul><h3 id="products-and-prices" tabindex="-1">Products and prices <a class="header-anchor" href="#products-and-prices" aria-label="Permalink to &quot;Products and prices&quot;">​</a></h3><p>Define what you sell and at what price.</p><ul><li><a href="./products-prices/">Products and prices</a>: overview of the group.</li><li><a href="./products-prices/manage-products.html">Manage products</a>: create goods and services.</li><li><a href="./products-prices/product-variants.html">Product variants</a>: sell one product in several versions.</li><li><a href="./products-prices/price-lists.html">Price lists</a>: set prices for groups of customers.</li><li><a href="./products-prices/discounts-margins.html">Discounts and margins</a>: discount lines and see your profit.</li><li><a href="./products-prices/sell-in-other-currencies.html">Sell in other currencies</a>: quote in another currency.</li></ul><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p>Set these up once, before your first quotation.</p><ul><li><a href="./configuration/">Configuration</a>: overview of the group.</li><li><a href="./configuration/settings.html">Settings</a>: turn module features on or off.</li><li><a href="./configuration/product-categories.html">Product categories</a></li><li><a href="./configuration/product-attributes.html">Product attributes</a></li><li><a href="./configuration/packagings.html">Packagings</a></li><li><a href="./configuration/tags.html">Tags</a></li><li><a href="./configuration/uom-categories.html">UOM categories</a></li></ul><h2 id="where-to-start-1" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start-1" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><ol><li>Review the <a href="./configuration/settings.html">settings</a> and turn on the features you need.</li><li>Create your <a href="./products-prices/manage-products.html">products</a> and a <a href="./quotations-orders/manage-customers.html">customer</a>.</li><li><a href="./quotations-orders/create-quotation.html">Create your first quotation</a>, confirm it and invoice it.</li></ol>',21)]))}const p=o(i,[["render",s]]);export{f as __pageData,p as default};
